// P1, the single-cylinder four-stroke engine, built end to end: bundles build.ts with the facade and the cad-model core
// (as cad-model's own test runner bundles its tests) and runs it. Deterministic and rerunnable:
//   node examples/products/engine-1cyl/run.mjs <out-dir>
// writes <out-dir>/report.json (each part's volume, mass and evaluation time) and the documents; engine.bcad beside
// this file is the assembly, regenerated byte for byte.
import { build } from 'esbuild';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { spawnSync } from 'node:child_process';

const here = import.meta.dirname, out = resolve(process.argv[2] ?? join(here, 'out'));
const dir = mkdtempSync(join(tmpdir(), 'engine-1cyl-'));
try {
  await build({ entryPoints: [join(here, 'build.ts')], outfile: join(dir, 'build.mjs'), bundle: true, platform: 'node', format: 'esm', target: 'node22', logLevel: 'warning', define: { 'import.meta.dirname': JSON.stringify(here) } });
  const r = spawnSync(process.execPath, [join(dir, 'build.mjs'), out], { stdio: 'inherit' });
  process.exitCode = r.status ?? 1;
} finally { rmSync(dir, { recursive: true, force: true }); }
